/* crosswalk cards, r40. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40a"]=[{"q": "With STOP 0, LOAD 1, ADD 2, STORE 3, SUB 4, JZ 5, JMP 6, which number is the line “STORE 92”?", "a": "392", "w": ["923", "92", "302"], "why": "Word-for-number: 100·3 + 92."}, {"q": "Which line is the instruction 509?", "a": "JZ 9", "w": ["JMP 9", "SUB 9", "LOAD 509"], "why": "The first digit 5 is JZ, and 09 is its cell."}, {"q": "“top:” stands before a line. How many cells does the label take?", "a": "none", "w": ["one", "two", "as many as the line"], "why": "A label names the address of the line it stands before; it is not a line."}, {"q": "In “LOAD count”, what does count stand for?", "a": "a cell", "w": ["the letter c", "a label", "an instruction"], "why": "A name stands for a cell; the line loads the number held there."}, {"q": "The assembler’s first pass gives each label what?", "a": "the count of lines before it", "w": ["its own cell", "the digit of its word", "the number it jumps to"], "why": "The first pass counts lines and fixes one address per label."}, {"q": "A new line is put near the top of a program written with labels. What must be changed by hand?", "a": "nothing: assemble again", "w": ["every jump after it", "every label", "every name"], "why": "The first pass hands every label its new address."}, {"q": "Does assembling change what the program does?", "a": "no", "w": ["yes, it shortens the run", "yes, it moves the jumps", "only when a label moves"], "why": "Each line becomes the one number it names, so the run is the same."}, {"q": "Words such as LOAD and JZ for instruction digits. What are they called?", "a": "mnemonics", "w": ["labels", "opcodes in numbers", "symbolic cells"], "why": "The cellar: the words are mnemonics, and a program in them is assembly language."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40b"]=[{"q": "JZ yes; Q; JMP end; yes: P; end:. Which shape is this?", "a": "an if", "w": ["a while", "a row of steps", "a call"], "why": "Choice is a skip: one jump skips Q, the other skips P."}, {"q": "In the if shape, how many of P and Q run?", "a": "exactly one", "w": ["both", "at least one", "neither, if A is 0"], "why": "Branch technique: A is 0 or it is not, and one path runs."}, {"q": "top: JZ end; P; JMP top; end:. How many times may P run?", "a": "possibly none", "w": ["at least once", "exactly once", "for ever"], "why": "The test is at the top, so the body may never run."}, {"q": "JZ end. When does it jump?", "a": "when A is 0", "w": ["when A is not 0", "always", "when A is 1"], "why": "Jump if zero."}, {"q": "Which three shapes are enough for every flow chart?", "a": "sequence, if, while", "w": ["if, call, jump", "sequence, jump, stop", "while, call, return"], "why": "40b3 rewrites any chart in the three shapes."}, {"q": "The rewrite of any chart into the three shapes needs what extra?", "a": "one cell, next", "w": ["one extra jump per box", "a pile", "a second machine"], "why": "next keeps the number of the box to visit."}, {"q": "Why do the three shapes beat bare jumps for proof?", "a": "each piece has one way in and one way out", "w": ["they run faster", "they use fewer cells", "they need no tests"], "why": "A claim can be written beside each piece and proved piece by piece."}, {"q": "Writing only in sequence, selection and iteration. What is it called?", "a": "structured programming", "w": ["assembly language", "recursion", "flow charting"], "why": "The cellar names it; 40b3 is the structured program theorem."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40c"]=[{"q": "x ← x + 1. What is it?", "a": "a step", "w": ["a sameness", "a totally false statement", "a definition"], "why": "← is a step: work out the right side, then put it in x."}, {"q": "As a statement about whole numbers, x = x + 1 is what?", "a": "totally false", "w": ["true for 0", "true for every x", "a step"], "why": "No number is its own next."}, {"q": "x held 4, then x ← x + 1. What does x hold?", "a": "5", "w": ["4", "x + 1", "both 4 and 5"], "why": "The new value is e’s value from before the step."}, {"q": "The list of what every name holds right now. What is it called?", "a": "the state", "w": ["the trace", "the program", "the type"], "why": "A run is a row of states, one per step."}, {"q": "x = 3, y = 8, then x ← y; y ← x. What do x and y hold?", "a": "8 and 8", "w": ["8 and 3", "3 and 8", "3 and 3"], "why": "After the first step the old x is gone."}, {"q": "To swap x and y, what is needed?", "a": "a third name", "w": ["two steps in either order", "a jump", "a sameness"], "why": "t keeps the old x."}, {"q": "From x = 1: y ← 2x; x ← x + 1. What does y hold?", "a": "2", "w": ["4", "3", "1"], "why": "Order matters: y reads x before x changes."}, {"q": "A name that holds a changing value. What is it called?", "a": "a variable", "w": ["a constant", "a label", "a mnemonic"], "why": "The cellar: a variable, and the step is assignment."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40d"]=[{"q": "CALL f. What does it put on the pile?", "a": "the address of the next line", "w": ["the address of f", "the value of f", "the whole program"], "why": "The way back goes on top of the pile."}, {"q": "RET. Where does the run go?", "a": "the address on top of the pile", "w": ["the start of the caller", "the start of f", "the end of the program"], "why": "RET takes the top way back off the pile."}, {"q": "f calls g. Which returns first?", "a": "g", "w": ["f", "either", "both at once"], "why": "Returns come in the reverse order of calls."}, {"q": "Last in, first out. Why must calls use that order?", "a": "a call returns only after every call it made", "w": ["it is faster", "the machine has one cell", "jumps go forwards"], "why": "So the way back must be kept on a pile."}, {"q": "fact(n): if n = 0 give 1, otherwise n · fact(n − 1). What is fact(3)?", "a": "6", "w": ["3", "9", "1"], "why": "Each return multiplies: 1, 1, 2, 6."}, {"q": "fact(3) runs. How many ways back are on the pile at its deepest?", "a": "four", "w": ["three", "one", "none"], "why": "fact(3), fact(2), fact(1), fact(0)."}, {"q": "Each call of fact keeps its own n. Where?", "a": "on the pile with its way back", "w": ["in one shared cell", "in a label", "nowhere: n is fixed"], "why": "Own-names technique."}, {"q": "The names a call puts on the pile. What are they called together?", "a": "its stack frame", "w": ["its state", "its label", "its type"], "why": "The cellar: the pile is the call stack."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40e"]=[{"q": "fact(k + 1) = (k + 1) · fact(k), assuming fact(k) = k!. What proof is running?", "a": "induction on n", "w": ["a falling measure", "a type check", "a trace table"], "why": "The program’s call is the proof’s step."}, {"q": "To prove a function that calls itself, assume it right on what?", "a": "smaller inputs", "w": ["the same input", "every input", "no input"], "why": "Assuming it on the same input is circular."}, {"q": "Each call is on n − 1. Why does every run of calls stop?", "a": "a falling run of whole numbers stops", "w": ["n is small", "the pile is finite", "the program says so"], "why": "Falling-measure technique, from every set of whole numbers having a least member."}, {"q": "gcd(a, b) calls gcd(b, r). Which number falls?", "a": "b", "w": ["a", "a + b", "r − b"], "why": "A remainder is less than its divisor."}, {"q": "1, 1/2, 1/4, … Can it serve as a falling measure?", "a": "no: it falls for ever", "w": ["yes: it falls", "yes: it is bounded", "only if it reaches 0"], "why": "The measure must be a whole number."}, {"q": "g(n) calls g(n/2) when n is even, g(3n + 1) when n is odd. Is a measure known?", "a": "no: whether it always stops is open", "w": ["yes: n", "yes: n/2", "yes: 3n + 1"], "why": "40e4: nobody knows a measure for it."}, {"q": "A falling whole-number measure for a program. What is it called?", "a": "a variant", "w": ["an invariant", "a type", "a state"], "why": "The cellar: a variant, or ranking function."}, {"q": "Proving a recursive function by induction over its calls. What is it called?", "a": "structural induction", "w": ["strong recursion", "a trace", "total testing"], "why": "The cellar names it."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40f"]=[{"q": "{P} c {Q}. What does it promise?", "a": "if P before and c stops, Q after", "w": ["c stops", "Q before c", "P and Q always"], "why": "The triple says nothing about stopping."}, {"q": "{x = 2} x ← x + 1 {?}. What goes in the gap?", "a": "x = 3", "w": ["x = 2", "x = x + 1", "x = 1"], "why": "The new x is the old x + 1."}, {"q": "To have y > 3 after y ← x + 1, what is needed before?", "a": "x > 2", "w": ["y > 3", "x > 3", "y > 2"], "why": "Backwards-assignment: put x + 1 in y’s place."}, {"q": "{Q[e/x]} x ← e {Q}. Which technique?", "a": "backwards-assignment", "w": ["sequence", "consequence", "choice"], "why": "Assignment reads backwards."}, {"q": "From {P} c₁ {R} and {R} c₂ {Q}, write {P} c₁; c₂ {Q}. Which technique?", "a": "sequence", "w": ["consequence", "choice", "while"], "why": "Two promises chain through R."}, {"q": "{x > 5} y ← x + 1 {y > 3} from {x + 1 > 3} y ← x + 1 {y > 3}. Which technique finishes it?", "a": "consequence", "w": ["sequence", "choice", "backwards-assignment"], "why": "A promise may be asked of a stronger start."}, {"q": "{P} x ← e {P[e/x]}. Is it allowed?", "a": "no: it reads the technique forwards", "w": ["yes", "only for numbers", "only if e is x"], "why": "From x = 0, x ← 5 would promise 5 = 0."}, {"q": "A triple that says nothing about stopping. What does it state (Hoare triple)?", "a": "partial correctness", "w": ["total correctness", "termination", "type soundness"], "why": "The cellar: P is the precondition, Q the postcondition."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40g"]=[{"q": "From {I ∧ B} c {I}, write {I} while B do c {I ∧ ¬B}. What is I called?", "a": "the invariant", "w": ["the measure", "the test", "the goal"], "why": "I holds at the top of every turn."}, {"q": "p ← 0; k ← K; while k ≠ 0: p ← p + x; k ← k − 1. Which statement does each turn keep?", "a": "p + kx = Kx", "w": ["p = Kx", "k = K", "p + k = K"], "why": "It holds at the start and survives each turn."}, {"q": "When the loop ends, what holds besides I?", "a": "the test fails", "w": ["the test passes", "the body ran once", "k = K"], "why": "So I ∧ ¬B holds."}, {"q": "Does an invariant prove the loop stops?", "a": "no: a falling whole number does", "w": ["yes", "only for while loops", "only if B is false"], "why": "Stopping needs a measure."}, {"q": "Where must the invariant hold?", "a": "at the top of each turn", "w": ["between every two steps", "only at the end", "only at the start"], "why": "In the middle of the body it may fail."}, {"q": "Euclid’s loop: which number falls?", "a": "b", "w": ["a", "gcd(a, b)", "r + b"], "why": "A remainder is less than its divisor."}, {"q": "x = x as an invariant. What is wrong?", "a": "with ¬B it gives nothing", "w": ["it is not kept", "it is false", "it stops the loop"], "why": "The invariant must give the goal at the end."}, {"q": "An invariant together with a falling measure. What is the whole promise called?", "a": "total correctness", "w": ["partial correctness", "type soundness", "a variant"], "why": "Partial correctness together with termination."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40h"]=[{"q": "x : number. What does it say?", "a": "x may hold only whole numbers", "w": ["x is a number now", "x is 0", "x is a label"], "why": "A type is the set a name may hold."}, {"q": "+ takes two numbers. What does ∧ take?", "a": "two truth values", "w": ["two numbers", "a number and a truth value", "a list"], "why": "Each operation says which types it takes and gives."}, {"q": "Does the type check run the program?", "a": "no: it reads each line once", "w": ["yes, once", "yes, on every input", "only the loops"], "why": "Checking without running."}, {"q": "x ← y / z with z holding 0. Does it pass the check?", "a": "yes: both sides are numbers", "w": ["no: division by 0", "no: z is wrong", "only if y is 0"], "why": "A check sees kinds, not values."}, {"q": "A program passes the check. Is it correct?", "a": "not shown: only no wrong kinds", "w": ["yes", "yes, if it stops", "no"], "why": "Types leave wrong answers to 40f and 40e."}, {"q": "x ← x + true. What does a typed program say?", "a": "it fails: a truth value is not a number", "w": ["fine: true is 1", "fine: true is 0", "it passes at run time"], "why": "A typed program keeps the kinds apart."}, {"q": "A member of a type is like what for a statement?", "a": "a showing of it", "w": ["its negation", "its name", "its rows"], "why": "Types look like statements."}, {"q": "“Well-typed programs cannot go wrong.” What is it called?", "a": "type soundness", "w": ["type inference", "partial correctness", "the halting result"], "why": "The cellar names the type-check technique."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40i"]=[{"q": "A list is empty, or what?", "a": "a number in front of a list", "w": ["a pair of lists", "a number", "a tree"], "why": "The smallest set built from empty by putting in front."}, {"q": "length(h in front of t) = ?", "a": "1 + length(t)", "w": ["length(t)", "h + length(t)", "2 · length(t)"], "why": "One line per way a list is built."}, {"q": "Can a list hold itself?", "a": "no", "w": ["yes, if empty", "yes, if long", "only trees can"], "why": "Every list is built in finitely many steps."}, {"q": "A claim holds of empty, and of h in front of t whenever of t. Which technique gives every list?", "a": "shape-induction", "w": ["falling measure", "sequence", "the type check"], "why": "The lists are the smallest such set."}, {"q": "length(append(s, t)) = ? ", "a": "length(s) + length(t)", "w": ["length(s) · length(t)", "length(t)", "length(s) + 1"], "why": "Shape-induction on s."}, {"q": "A tree with n nodes. How many empty places below it?", "a": "n + 1", "w": ["n", "2n", "n − 1"], "why": "Each node adds one more empty place."}, {"q": "True for lengths 1, 2, 3. Is it proved for all lists?", "a": "no", "w": ["yes", "yes, by induction", "only for short lists"], "why": "Three cases are not a proof."}, {"q": "A number in front of a list. What is it often called?", "a": "cons", "w": ["append", "head", "nil"], "why": "The cellar: these are algebraic data types."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40j"]=[{"q": "A program held as a tree, run shape by shape. What runs it?", "a": "an interpreter", "w": ["a compiler", "an assembler", "the type check"], "why": "The interpreter does the shape on top and moves on."}, {"q": "A program turned into instruction numbers once and for all. What did it?", "a": "a compiler", "w": ["an interpreter", "the pile", "a trace table"], "why": "A compiler translates."}, {"q": "While compiles to which shape of 40b?", "a": "a test and a jump back", "w": ["a skip", "a call", "a label only"], "why": "40b2’s top: JZ end; body; JMP top; end:."}, {"q": "Why compiling-keeps-runs, from the parts?", "a": "shape-induction over the program", "w": ["testing every program", "the type check", "a falling measure"], "why": "Assignments are the start case."}, {"q": "Can the first compiler compile itself?", "a": "no: nothing runs it yet", "w": ["yes", "yes, twice", "only in numbers"], "why": "It is written below, in assembly."}, {"q": "Two right compilers give different numbers for one program. Is one wrong?", "a": "not necessarily", "w": ["yes, the newer", "yes, the longer", "yes, both"], "why": "A compiler keeps the runs, not the form."}, {"q": "Writing a compiler in its own language. What is it called?", "a": "bootstrapping", "w": ["interpreting", "assembling", "linking"], "why": "The cellar names it."}, {"q": "Two programs leave the same final state from every start. What are they for every run?", "a": "the same", "w": ["different", "equal in words", "one compiled"], "why": "Keep the runs, not the form."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40k"]=[{"q": "Goal s = n(n + 1)/2. Which guess loosens it?", "a": "s = i(i + 1)/2", "w": ["s = n", "i = n", "s = 0"], "why": "Replace the n worked toward by the name the loop moves."}, {"q": "Which three duties check an invariant?", "a": "start, keep, finish", "w": ["start, stop, type", "test, jump, stop", "before, middle, after"], "why": "All three are needed."}, {"q": "Carry I backwards through the body. Which duty is it?", "a": "keep", "w": ["start", "finish", "measure"], "why": "The turn must keep I."}, {"q": "n − i falls each turn. What must be added to I?", "a": "i ≤ n", "w": ["i ≥ n", "s ≥ 0", "i = 0"], "why": "Only then is n − i a whole number."}, {"q": "The start duty fails. Too weak or too strong?", "a": "too strong", "w": ["too weak", "neither", "both"], "why": "Drop what the start cannot give."}, {"q": "n + i as the falling number. What is wrong?", "a": "it rises", "w": ["it is not whole", "it is too slow", "nothing"], "why": "The measure must fall."}, {"q": "The three duties, accepted name?", "a": "verification conditions", "w": ["preconditions", "loop guards", "test cases"], "why": "The cellar names them."}, {"q": "The keep duty fails. Too weak or too strong?", "a": "too weak", "w": ["too strong", "neither", "the measure"], "why": "Add what the turn needs."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["40l"]=[{"q": "x ← y + z becomes what?", "a": "LOAD y; ADD z; STORE x", "w": ["ADD y; ADD z; STORE x", "STORE x; LOAD y; ADD z", "LOAD x; ADD y"], "why": "A pattern for each shape."}, {"q": "while x ≠ 0 becomes which pattern?", "a": "top: LOAD x; JZ end; body; JMP top; end:", "w": ["LOAD x; JMP top", "JZ top; body", "top: body; JZ top"], "why": "40b2’s shape."}, {"q": "Why keep 1 and 0 in cells?", "a": "the machine adds and takes away only cells", "w": ["for labels", "for the pile", "to save time"], "why": "Constants need cells of their own."}, {"q": "JZ top in place of JZ done. What breaks?", "a": "the loop never leaves", "w": ["nothing", "the body is skipped", "the labels move"], "why": "The test must leave the loop when n is 0."}, {"q": "JMP top left out. What happens?", "a": "the body runs once and falls through", "w": ["the loop runs for ever", "nothing", "the program will not assemble"], "why": "The jump back makes the loop."}, {"q": "The source gives s = 6 and the numbers leave 6. What does it check?", "a": "the runs agree", "w": ["the numbers are shortest", "the types pass", "the labels are right"], "why": "As 40j2 promised."}, {"q": "Choosing which values live in which cells. Accepted name?", "a": "register allocation", "w": ["code generation", "linking", "assembly"], "why": "The cellar names it."}, {"q": "Turning shapes into instructions. Accepted name?", "a": "code generation", "w": ["interpreting", "parsing", "bootstrapping"], "why": "The cellar names it."}];
