(window.LADDER_CARDS["40a"]=window.LADDER_CARDS["40a"]||[]).push(
 {"u":"40a1.1","q":"What does the word-for-number technique say? Which number is the line “STORE 92”?","a":"Each word stands for exactly one first digit d, so a line “word n” names exactly one instruction number, 100d + n; STORE stands for 3, so the line is 100 · 3 + 92 = 392","w":["Each word stands for exactly one cell, so a line names a cell; “STORE 92” is cell 92","Each word stands for exactly one first digit d, so a line names the number d + n; “STORE 92” is 95","A word may stand for several digits, chosen by the assembler; “STORE 92” is 192 or 392"],"why":"It is the instruction-number technique of 39j1, run backwards."},
 {"u":"40a2.1","q":"What does a name stand for, and what does a label stand for? Why does a label take no cell?","a":"A name stands for a cell, as x for cell 90; a label marks a line and stands for the address of the line it is written before; a label is not a line, so it gets no number of its own","w":["A name stands for a number held in a cell, and a label for a cell; a label takes the cell after its line","A name stands for a line and a label for a cell; a label takes no cell because it is deleted before the run","A name and a label both stand for instructions; a label takes no cell because jumps are not stored"],"why":"“top:” before the line in cell 0 names the address 0."},
 {"u":"40a3.1","q":"What do the two passes do? Why does the assembled program run exactly as the numbers it names?","a":"The first pass counts lines and gives each label the count of lines before it; the second replaces each word by its digit and each name or label by its number; each line becomes the one number it names and each label one address, so the assembled program is those numbers","w":["The first pass runs the program and the second checks it; the two runs agree because the program is run twice","The first pass replaces the words and the second deletes the labels; the program runs the same because labels do nothing","Both passes count lines; the program runs the same only when it has no jumps"],"why":"The assembler is a function from lists of lines to lists of numbers, and a program too."},
 {"u":"40a4.1","q":"What changes when a line is added, in numbers and in words? Why does the first pass make the labels safe?","a":"In numbers, every jump to a cell past the new line must be found and changed by hand; in words, nothing is changed; the first pass counts the lines again at each run and hands every label its new address","w":["In numbers nothing changes, and in words every label must be renamed; the first pass renames them","In both, every jump must be changed by hand; the first pass only finds the jumps","In numbers the program stops working for good; in words the new line is skipped by the first pass"],"why":"A jump says where it goes by what is there, not by how far down it is."},
 {"u":"40a5.1","q":"Why is “LOAD x” not about the letter x? Why does assembling not change what a program does?","a":"x is a name for cell 90, and the line loads the number held in cell 90; and each line becomes the one number it names, so the run is the run of those numbers","w":["x is the number 90, and the line loads 90; and assembling shortens the program, so it runs faster","x is a label for a line, and the line jumps there; and assembling changes the program only at its labels","The line loads the letter x as a number; and assembling changes what the program does on its first pass"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40b"]=window.LADDER_CARDS["40b"]||[]).push(
 {"u":"40b1.1","q":"How is an if written with jumps? Why does exactly one of P and Q run?","a":"JZ yes; Q; JMP end; yes: P; end:; A is 0 or it is not: if A is 0 the run skips Q, runs P and reaches end, and if not it runs Q and the jump to end skips P","w":["JMP yes; Q; JZ end; yes: P; end:; both P and Q run, in that order","JZ yes; P; yes: Q; end:; P and Q both run when A is not 0","JZ end; P; Q; end:; neither runs when A is 0, and both run otherwise"],"why":"One path, either way: the branch technique."},
 {"u":"40b2.1","q":"How is a while written with jumps? Why may its body run no times?","a":"top: JZ end; P; JMP top; end:; the test is at the top, so if A is 0 on arrival the run jumps to end before P","w":["top: P; JZ end; JMP top; end:; the body always runs once before the test","top: JZ end; P; end:; the body runs once at most, since nothing jumps back","top: JMP top; P; JZ end; end:; the body may run no times because the test is at the bottom"],"why":"The shape has one way in, at top, and one way out, at end."},
 {"u":"40b3.1","q":"How does one extra cell let a while stand in for any chart? Why do the two runs agree?","a":"Number the boxes 1 to k and keep the box to visit next in the cell next; one while, running until next is 0, holds a chain of ifs, one per box, and each box sets next; each turn of the while runs exactly the box the chart would have reached, by the branch technique on each if, so the actions come in the same order","w":["The extra cell counts the turns of the while; the runs agree because both make k turns","The extra cell keeps the result of every test; the runs agree only for charts with no loops","The extra cell holds the whole chart; the runs agree because the while runs every box at each turn"],"why":"Sequence, if and while are enough."},
 {"u":"40b4.1","q":"What does one way in and one way out make possible? Why is a jump into the middle of a loop a problem?","a":"A claim about a piece can be written beside it and proved piece by piece, as 40f and 40g do; a jump into the middle leaves no such seam, since the piece is entered without passing its way in","w":["It makes the program run faster; a jump into the middle slows the loop","It lets a piece be run backwards; a jump into the middle makes the loop run for ever","It lets pieces be run in any order; a jump into the middle is not allowed by the machine"],"why":"A program in the three shapes reads from top to bottom."},
 {"u":"40b5.1","q":"When does JZ jump? Why does the rewrite need the extra cell next?","a":"It jumps when A is 0; and the proof keeps the number of the box to visit in next, which is how each turn of the while knows which box to run","w":["It jumps when A is not 0; and next is needed to count the boxes","It jumps on every turn; and the rewrite needs no new cell","It jumps when A is 0; and next is needed to hold the value of A during a test"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40c"]=window.LADDER_CARDS["40c"]||[]).push(
 {"u":"40c1.1","q":"What does x ← e do? Why is x = x + 1 totally false as a statement but fine as a step?","a":"It works out e with the values held now and then puts the result in x; as a statement, no number is its own next; as a step, x held 4 and now it holds 5","w":["It says that x and e are the same; x = x + 1 is true as a statement when x is large","It puts x into e; x = x + 1 is fine as a statement and totally false as a step","It works out e after changing x; x ← x + 1 never ends, since x keeps growing"],"why":"One mark for two jobs is the old trouble of 0b9; the ladder keeps ← for the step."},
 {"u":"40c2.1","q":"What does the assignment technique say? What is a trace table a list of?","a":"The step x ← e changes x and nothing else, and the new value of x is the value e had before the step; a trace table lists the states of a run, one row per step, each made from the one before","w":["The step x ← e changes x and every name in e; a trace table lists the lines of the program","The step x ← e changes x to the value e has after the step; a trace table lists the names","The step x ← e changes nothing until the program stops; a trace table lists the final state only"],"why":"The state is the list of what each name holds."},
 {"u":"40c3.1","q":"Why does x ← y; y ← x fail to swap? What is t for?","a":"After the first step both hold the old y, and the old x is gone; t keeps the old x, so that y can take it after x has taken the old y","w":["The two steps undo each other, leaving x and y as they were; t counts the steps","After the first step both hold the old x; t keeps the old y","The steps swap correctly; t is only there to make the trace table longer"],"why":"t ← x; x ← y; y ← t takes 3, 8 to 8, 3."},
 {"u":"40c4.1","q":"Why do the two orders leave different values of y? Why do steps not turn about as an and does?","a":"From x = 1, x ← x + 1; y ← 2x gives y = 4, and y ← 2x; x ← x + 1 gives y = 2; a step reads the state the step before it left, so the order is part of what is done","w":["Both orders give y = 4, since x ends at 2 either way; steps turn about as an and does","The first order gives y = 2 and the second y = 4; steps turn about only when they use different names","The orders differ because 2x is worked out twice; steps turn about whenever they are on one line"],"why":"The two parts of an and can be turned about (1c3); steps in a row cannot."},
 {"u":"40c5.1","q":"Why does x ← y; y ← x not swap? Why can two steps not be run in either order?","a":"After the first step the old x is gone, so a third box is needed; and each step reads the state the one before left","w":["The second step undoes the first; and two steps can be run in either order when both are steps","x and y hold the same value to begin with; and steps are run backwards","A swap needs four steps; and the order matters only for jumps"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40d"]=window.LADDER_CARDS["40d"]||[]).push(
 {"u":"40d1.1","q":"What do CALL and RET do? How does each call get back to its own caller?","a":"CALL f puts the address of the next line on the pile and jumps to f; RET takes the top address off the pile and jumps to it; each call left its own way back on top of the pile","w":["CALL f jumps to f and RET jumps to the start of the program; each call gets back by a label","CALL f copies the function into the caller and RET deletes it; no way back is needed","CALL f puts the address of f on the pile and RET jumps to the bottom address; every call returns to the first caller"],"why":"The function is written once and used from many places."},
 {"u":"40d2.1","q":"Why do returns come in reverse order of calls? What goes wrong with a single cell for the way back?","a":"A call cannot return until every call it made has returned, which is a pile’s order, last in and first out (39n1); with a single cell, g’s call would overwrite f’s way back, and f would never get home","w":["Returns come in the order of the calls, first in and first out; a single cell works when calls nest","Returns come in reverse order because the machine runs backwards after a call; a single cell is only slower","A call returns before the calls it made; with a single cell every call returns twice"],"why":"Calls nest: f calls g, and g returns before f does."},
 {"u":"40d3.1","q":"How is fact 4d’s defining by repeating? How deep does the pile get for fact(3)?","a":"It has a start, fact(0) = 1, and a step, fact(n) = n · fact(n − 1), written as a program that calls itself; fact(3) calls fact(2), fact(1) and fact(0), so four ways back are on the pile before it begins to empty","w":["It has a step and no start; the pile holds one way back, reused by each call","It has a start, fact(1) = 0, and a step that adds; the pile holds three ways back","It is a loop with a counter and makes no calls; the pile stays empty"],"why":"Each return multiplies: 1, 1, 2, 6."},
 {"u":"40d4.1","q":"What does the own-names technique say? What would go wrong if every call of fact shared one n?","a":"A call’s names live on the pile with its way back, so a call changes no name of any call that is waiting for it; with one shared cell, fact(2) would overwrite the 3 that fact(3) still needs","w":["Every call shares the names of its caller, so a call can change them; nothing goes wrong, since n only falls","A call’s names live in fixed cells chosen by the assembler; a shared n would make fact run faster","A call has no names of its own; a shared n would stop fact from calling itself"],"why":"A return takes the names off with the way back."},
 {"u":"40d5.1","q":"Where does RET go? Why does fact stop?","a":"To the line after the call, the address on top of the pile; and fact stops when it reaches its start case, 0, which makes no call","w":["To the start of the caller; and fact stops when the pile is full","To the line of the call itself, which runs again; and fact never stops, since it calls itself","To the bottom address of the pile; and fact stops after three calls whatever n is"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40e"]=window.LADDER_CARDS["40e"]||[]).push(
 {"u":"40e1.1","q":"Why is induction the right tool for fact? Which line of the program gives the proof’s step?","a":"A recursive program and its induction have the same shape: the program’s start case, fact(0) = 1 = 0!, is the proof’s start, and the program’s call, fact(k + 1) = (k + 1) · fact(k), gives the step, (k + 1) · k! = (k + 1)!","w":["Induction is right because fact has a loop; the line fact(0) = 1 gives the step","Induction is right because n! is large; the step comes from running fact on three inputs","A program cannot be proved right for every input; induction only checks the start case"],"why":"The claim is fact(n) = n! for every whole number n."},
 {"u":"40e2.1","q":"What does the falling-measure technique say? Why can a falling run of whole numbers not go on for ever?","a":"If each call is on an input whose whole-number measure is smaller than the caller’s, then every run of calls stops; the set of values of an endless falling run would have no least member, and 4h says every non-empty set of whole numbers has one","w":["If each call is on a larger input, the run stops; a rising run of whole numbers has a greatest member","If each call is on a smaller input of any kind, the run stops; a falling run of any numbers ends at 0","If the measure falls on the first call, the run stops; whole numbers cannot fall at all"],"why":"It is the technique of 4l2, with the calls as the moves."},
 {"u":"40e3.1","q":"What is the measure for gcd, and why does it fall? Why is gcd(a, b) = gcd(b, r)?","a":"The measure is b, and it falls because a remainder is less than its divisor (4j); a = qb + r, so whatever divides b and r divides a, and whatever divides a and b divides r = a − qb","w":["The measure is a, and it falls because b is less than a; the divisors are the same because r divides both","The measure is the pair a, b, and it falls because both are halved; the divisors are the same because a = b + r","There is no measure, since the input is a pair; the common divisors differ, and only the greatest is kept"],"why":"So the greatest one is the same, and gcd(a, 0) = a is the start."},
 {"u":"40e4.1","q":"Why is the falling-measure technique a tool and not a test? What is known about the function that halves or triples and adds one?","a":"Not every function that calls itself stops, and for some nobody knows a measure; g calls g(n/2) when n is even and g(3n + 1) when n is odd, and whether it stops for every n is an old open question; rung 41 shows that no machine can find such a measure for every program","w":["Every function has a measure, found by running it; g is proved to stop for every n","The technique tests any program by machine; g is proved never to stop","A function with no known measure never stops; g stops only for even n"],"why":"A measure, once found, proves stopping; nothing promises one will be found."},
 {"u":"40e5.1","q":"Why may the proof assume the function right only on smaller inputs? Why must the measure be a whole number?","a":"Assuming fact(n) right to prove fact(n) right is circular; and a falling run of fractions, 1, 1/2, 1/4, …, falls for ever, while a falling run of whole numbers stops","w":["The proof may assume it on every input, since it is true; and the measure may be any number that falls","Smaller inputs run faster; and whole numbers are easier to store in a cell","The proof assumes it on larger inputs; and the measure must be a whole number because inputs are"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40f"]=window.LADDER_CARDS["40f"]||[]).push(
 {"u":"40f1.1","q":"What does {P} c {Q} say? Why does it say nothing about stopping?","a":"For every state in which P holds, if c runs and stops, then Q holds in the state after; the stopping is inside the if, so the triple promises Q only when c stops, and stopping is proved apart, by 40e’s measure","w":["For some state in which P holds, c runs and Q holds after; it says c stops, since Q is reached","For every state, P and Q both hold while c runs; stopping follows from P","If Q holds after c, then P held before; it says nothing about stopping because c always stops"],"why":"It is an every around an if (2b10): {x = 2} x ← x + 1 {x = 3}."},
 {"u":"40f2.1","q":"What does the backwards-assignment technique say? Why does it run backwards?","a":"{Q[e/x]} x ← e {Q}, where Q[e/x] is Q with e put in every gap marked x; x after the step holds what e held before (40c2), so whatever Q says of x afterwards, Q[e/x] said of e beforehand","w":["{P} x ← e {P[e/x]}; it runs forwards because the step runs forwards","{Q} x ← e {Q}; an assignment changes no condition","{Q[x/e]} x ← e {Q}; it runs backwards because e after the step holds what x held before"],"why":"To have y > 3 after y ← x + 1, have x + 1 > 3 before, which is x > 2."},
 {"u":"40f3.1","q":"What does the sequence technique need in the middle? Why is the choice technique reasoning by cases?","a":"A middle condition R, with {P} c₁ {R} and {R} c₂ {Q}, to give {P} c₁; c₂ {Q}; and B holds or it does not: from {P ∧ B} c₁ {Q} and {P ∧ ¬B} c₂ {Q} either case ends in Q, and the branch technique of 40b1 runs the right one","w":["Nothing: any two triples chain; the choice technique runs both branches and keeps the better","The same condition P before both pieces; the choice technique is induction on B","A middle condition R that is totally false; the choice technique needs B to hold in both branches"],"why":"The first chains two promises as 1d chains ifs; the second is 1c7."},
 {"u":"40f4.1","q":"What does the consequence technique say? How does it give {x > 5} y ← x + 1 {y > 3}?","a":"If P′ ⇒ P, {P} c {Q} and Q ⇒ Q′, then {P′} c {Q′}; backwards-assignment gives {x + 1 > 3} y ← x + 1 {y > 3}, and x > 5 gives x + 1 > 3, so {x > 5} y ← x + 1 {y > 3}","w":["If P ⇒ P′ and Q′ ⇒ Q, then {P′} c {Q′}; the worked triple follows because x > 2 gives x > 5","If {P} c {Q}, then {Q} c {P}; the worked triple is turned about","If P′ ⇒ P and {P} c {Q}, then {P′} c {P}; the worked triple needs no assignment technique"],"why":"A promise may be asked of a stronger start and weakened at the end."},
 {"u":"40f5.1","q":"Why does assignment not run forwards? Why can a triple not be turned about?","a":"The technique forwards, {P} x ← e {P[e/x]}, would promise 5 = 0 after x ← 5 from x = 0; and a program does not run backwards: x ← 0 takes every x to 0","w":["Forwards it is the same technique; and a triple can be turned about whenever c stops","Assignment runs forwards only for numbers above 0; and a triple turns about when P and Q are the same","The forwards technique is right but longer; and turning about fails only for loops"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40g"]=window.LADDER_CARDS["40g"]||[]).push(
 {"u":"40g1.1","q":"What does the while technique say? Why does I hold at the top of every turn?","a":"From {I ∧ B} c {I}, write {I} while B do c {I ∧ ¬B}; if I holds before a turn and the test B passes, the body leaves I holding again, so I holds at the top of every turn by induction on the number of turns (4c)","w":["From {I} c {B}, write {I} while B do c {B}; I holds at every turn because B does","From {I ∧ B} c {I}, write {I} while B do c {I ∧ B}; I holds because the loop never ends","From {I ∧ ¬B} c {I}, write {B} while B do c {I}; I holds only at the last turn"],"why":"When the loop ends it ends because B failed, so I ∧ ¬B holds."},
 {"u":"40g2.1","q":"What is the invariant of the multiplying loop? Why does one turn keep it?","a":"p + kx = Kx; a turn sets p to p + x and k to k − 1, and (p + x) + (k − 1)x = p + kx = Kx","w":["p = Kx; a turn keeps it because p does not change","p + k = K; a turn adds 1 to p and takes 1 from k","pk = Kx; a turn multiplies p by x and divides k by x"],"why":"At k = 0 the invariant reads p = Kx: the loop multiplies."},
 {"u":"40g3.1","q":"Which number falls in the multiplying loop? What do the invariant and the measure give together?","a":"k falls by 1 each turn, and the loop ends when it reaches 0; a falling measure with an invariant gives the whole promise: the loop stops, and when it stops the goal holds","w":["p falls by x each turn; together they give only that the loop stops","k rises by 1 each turn; together they give that the invariant fails at the end","Nothing falls, since the while technique proves stopping; the measure adds nothing"],"why":"It is 40e’s falling-measure technique, with each turn counted as a call."},
 {"u":"40g4.1","q":"What does Euclid’s loop keep, and what falls? Why is a the answer when b = 0?","a":"It keeps gcd(a, b) = gcd(a₀, b₀), by 40e3, and b falls, since a remainder is less than its divisor; the loop ends with b = 0, and gcd(a, 0) = a, so a = gcd(a₀, b₀)","w":["It keeps a + b, and a falls; a holds the answer because it is the smaller of the two","It keeps gcd(a, b) = gcd(a₀, b₀), and nothing falls; a holds the answer because the loop runs b₀ times","It keeps ab = a₀b₀, and b falls; b holds the answer when the loop ends"],"why":"The invariant with ¬B gives the goal."},
 {"u":"40g5.1","q":"Why may the invariant fail in the middle of the body? Why is x = x a useless invariant?","a":"It is promised only at the top of each turn; between two steps of the body it may fail; and x = x is kept, but with ¬B it gives nothing: the invariant must give the goal at the end","w":["It never fails, since each step keeps it; and x = x is not kept by any loop","It fails in the middle because the test B fails there; and x = x is useless because it is totally false","It may fail at the top of a turn too; and x = x proves that the loop stops, nothing more"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40h"]=window.LADDER_CARDS["40h"]||[]).push(
 {"u":"40h1.1","q":"What is a type? What does an operation say about types?","a":"A type is a set of values (2d), such as the whole numbers, the two truth values or the strings of letters; each operation says which types it takes and which it gives: + takes two numbers and gives a number, and ∧ takes two truth values and gives one","w":["A type is a name for a cell; an operation says which cell it uses","A type is a value that a name holds now; an operation says what the value will be","A type is a set of programs; an operation says how long it runs"],"why":"x : number says x may hold only whole numbers."},
 {"u":"40h2.1","q":"What does the type-check technique say? Why does the check need no run?","a":"If a program passes the check and every name starts with a value of its type, then no run ever hands an operation a value outside the types it takes; each expression gets its type from its parts, by the lists of its operations, so the check reads each line once and never runs anything","w":["If a program passes the check, it gives the right answer on every input; the check runs the program once on each type","If a program passes the check, it stops on every input; the check needs no run because types are values","If one run hands every operation the right types, every run does; the check is that one run"],"why":"The proof is induction on the steps of a run."},
 {"u":"40h3.1","q":"Name two mistakes the type check passes. Which tools of this rung catch them?","a":"It passes x ← y / z when z holds 0, since both sides are numbers, and it passes a loop that never stops; 40f’s promises and 40e’s measures catch what types leave","w":["It passes x ← x + true and a test that is a number; the assembler catches them","It passes a division by 0 and a value of the wrong kind; nothing in this rung catches either","It passes no mistakes at all; 40f and 40e are needed only for untyped programs"],"why":"Types rule out one kind of mistake, a value of the wrong kind."},
 {"u":"40h4.1","q":"How is a function from A to B like an if? Where does the ladder make this exact?","a":"Give it an A and it makes a B, as an if gives its second part from its first; and a type with a member is like a statement that can be shown, the member being the showing; rung 47 makes this exact, as proofs are programs (47j)","w":["It is true when A and B are the same type; rung 41 makes this exact","It tests whether A holds and jumps to B, as JZ does; the ladder never makes it exact","It gives an A from a B, as an if run backwards; rung 40 makes this exact at 40j"],"why":"Types look like statements."},
 {"u":"40h5.1","q":"Why does passing the check not make a program correct? Why is x ← x + true refused?","a":"The check rules out values of the wrong kind, not wrong answers; and though 39a wrote true as 1 on the wire, a typed program keeps the kinds apart, and + takes two numbers","w":["A program that passes is correct on every input; and x ← x + true is allowed, since true is 1","The check runs the program and may miss a branch; and x + true is refused because true is 0","The check only counts the lines; and x + true is refused because x is not yet set"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40i"]=window.LADDER_CARDS["40i"]||[]).push(
 {"u":"40i1.1","q":"How are the lists defined? What does “smallest” rule out?","a":"The lists of numbers are the smallest set that holds the empty list and holds h in front of t whenever it holds t (4b); smallest means every list is built in finitely many steps from the empty list, so no list goes on for ever and no list holds itself","w":["The lists are every set of numbers; smallest rules out the empty list","A list is a number in front of a list, with no start; smallest rules out lists of one number","The lists are the largest set closed under putting in front; smallest rules out long lists"],"why":"A tree is empty, or a node holding a number with two trees below it."},
 {"u":"40i2.1","q":"Why does length have exactly two lines? Why does every call of length stop?","a":"It has one line for each way a list is built: length(empty) = 0, and length(h in front of t) = 1 + length(t); each call is on a part, so the size falls, and by 40e2 every call stops","w":["It has one line for even lists and one for odd; every call stops because lists are short","It has one line for each number in the list; every call stops because it makes no calls","It has two lines so that it can be checked twice; every call stops because 1 is added each time"],"why":"The function follows the shape of its input."},
 {"u":"40i3.1","q":"What does the shape-induction technique say? Why is it valid?","a":"If a claim holds of the empty list, and holds of h in front of t whenever it holds of t, then it holds of every list; the set of lists with the claim holds the empty list and is closed under putting in front, and the lists are the smallest such set, so all of them have the claim","w":["If a claim holds of the empty list, it holds of every list; valid because every list ends in the empty list","If a claim holds of three lists of different lengths, it holds of every list; valid by counting","If a claim holds of h in front of t, it holds of t; valid because a part is smaller than the whole"],"why":"length(append(s, t)) = length(s) + length(t), by shape-induction on s."},
 {"u":"40i4.1","q":"How many empty places has a tree with n nodes? Why does the step of the proof use two parts?","a":"n + 1; a node has two trees below it, so the step supposes the claim for both: n₁ + n₂ + 1 nodes and (n₁ + 1) + (n₂ + 1) empty places, which is one more","w":["n; the step uses two parts because a tree has two ends","2n; the step uses two parts, one for the node and one for its number","n + 1; the step uses two parts because the claim is proved twice, for lists and for trees"],"why":"The empty tree starts it: 0 nodes, 1 empty place."},
 {"u":"40i5.1","q":"Why do three cases not prove a claim for every list? What may the step assume?","a":"Three cases are not a proof: the step must hold for every t; and the step may assume the claim only for t, since the claim for h in front of t is the goal","w":["Three cases are enough when the lists have different lengths; the step may assume the claim for h in front of t","Three cases fail because lists have no lengths; the step may assume nothing","Three cases prove it for lists of up to three; the step may assume the claim for every list"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40j"]=window.LADDER_CARDS["40j"]||[]).push(
 {"u":"40j1.1","q":"What does an interpreter hold, and what does it do at each shape? Which step of rung 39 does it use?","a":"It holds the program as a tree of shapes (40i) with the state beside it; it looks at the shape on top, does it, and moves on: for x ← e it works out e and changes x, and for a while it checks the test and either runs the body again or leaves; this is 39j4’s program as data","w":["It holds the instruction numbers of the program; at each shape it writes more numbers; it uses 39j1","It holds only the state; at each shape it asks the user what to do; it uses 39h","It holds the program as a tree and translates it all before running; it uses 39f"],"why":"A program read by another program."},
 {"u":"40j2.1","q":"What does the compiling-keeps-runs technique say? Why is its proof a shape-induction?","a":"If each shape, compiled from compiled parts, runs as the shape does, then every compiled program runs as its source does; a program is built from shapes: assignments are the start case, and a row, an if or a while is the step, assuming its parts compile right (40i3)","w":["If a compiled program runs once as its source does, it always will; the proof is induction on the number of runs","If each shape compiles to one number, the program runs as its source; the proof counts the numbers","Every compiled program runs faster than its source; the proof is by running both"],"why":"An if becomes 40b1’s skip, and a while 40b2’s test and jump back."},
 {"u":"40j3.1","q":"Why can the first compiler not compile itself? What must it be written in?","a":"Nothing yet runs it; it must be written in something that already runs: assembly, which 40a’s assembler turns to numbers","w":["A compiler is not a program, so it cannot be compiled; it must be built from switches","It is too large to compile; it must be written in its own language and typed in twice","It can compile itself straight away; the first one needs nothing below it"],"why":"Later compilers can be written in the language they compile."},
 {"u":"40j4.1","q":"What sameness must a compiler keep? Why may two right compilers give different numbers?","a":"Two programs that leave the same final state from every start are the same for every purpose a run can see; a compiler must keep that sameness, not the words, and different numbers can have the same runs","w":["It must keep the words of the program; two right compilers always give the same numbers","It must keep the count of lines; two compilers differ only when one is wrong","It must keep the speed of the run; two compilers differ because machines differ"],"why":"Keep the runs, not the form."},
 {"u":"40j5.1","q":"How is an interpreter different from a compiler? Why could the first compiler not compile itself?","a":"An interpreter runs from the program held as data, while translating first is compiling; and nothing ran the first compiler yet, so it was written below, in a language that already ran","w":["An interpreter first turns the program into numbers and a compiler runs it line by line; the first compiler did compile itself","They are the same program under two names; the first compiler was built from wires","An interpreter checks types and a compiler does not; the first compiler was too slow to compile itself"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["40k"]=window.LADDER_CARDS["40k"]||[]).push(
 {"u":"40k1.1","q":"How is the guess made from the goal? What is the guess here?","a":"Replace the n the loop works toward by the name it moves, i; from the goal s = n(n + 1)/2 the guess is I: s = i(i + 1)/2","w":["Replace s by 0; the guess is 0 = n(n + 1)/2","Take the goal itself as the invariant; the guess is s = n(n + 1)/2","Replace i by n; the guess is s = n²"],"why":"Loosen the goal."},
 {"u":"40k2.1","q":"What are the three duties? How is the keep duty checked?","a":"Start: s = 0 and i = 0 give 0 = 0; keep: the turn leaves I holding; finish: I and i = n give the goal; keep is checked by carrying I backwards through the body (40f2) and showing that what comes out follows from I: i(i + 1)/2 + (i + 1) = (i + 1)(i + 2)/2","w":["Start, stop and count; keep is checked by running the loop three times","Start, keep and finish; keep is checked by carrying I forwards from the start to the end of the program","Guess, test and repeat; keep is checked by trying n = 1, 2, 3"],"why":"{I ∧ i ≠ n} body {I}: the turn keeps I."},
 {"u":"40k3.1","q":"Which number falls? Why must i ≤ n be added to the invariant?","a":"n − i falls by 1 each turn; it is a whole number only while i ≤ n, so i ≤ n joins the invariant: it starts true, each turn keeps it because the test said i ≠ n, and it ends with i = n","w":["i falls by 1 each turn; i ≤ n is added to make the loop faster","n + i falls each turn; i ≤ n is added because s may be too large","s falls each turn; i ≤ n is needed for the finish duty only"],"why":"A measure must be a whole number (40e)."},
 {"u":"40k4.1","q":"What does a failed keep duty say about the guess? What does a failed start say?","a":"A failed keep or finish says the guess is too weak: add what the turn needs, as i ≤ n was added; a failed start says it is too strong: drop what the start cannot give","w":["A failed keep says the guess is too strong; a failed start says it is too weak","Any failed duty says the program is wrong; the guess is never changed","A failed keep says the loop never stops; a failed start says the loop never runs"],"why":"The guess is mended and the three duties checked again."},
 {"u":"40k5.1","q":"Why is checking the start not enough? Why is n + i not a measure?","a":"All three duties are needed, start, keep and finish; and n + i rises, while a measure must fall each turn","w":["The start duty gives the other two; and n + i is a measure, since it is a whole number","The start may be skipped; and n + i is not a whole number","Only the finish duty matters; and n + i falls too fast"],"why":"Both are rows of the step’s Moves to Watch Out For."});
