(function(C){C["40e"]=(C["40e"]||[]).concat([{"q": "Does a falling run of fractions stop?", "a": "no: 1, 1/2, 1/4, … falls for ever; the measure must be a whole number", "w": ["yes, after ten calls", "yes", "yes, at 0"], "why": "Falling-measure technique."}, {"q": "To prove fact(n) right, may fact(n) be assumed right?", "a": "no: that is circular; assume it only on smaller inputs", "w": ["yes, for every n", "yes", "yes, at the start case"], "why": "Recursion is induction."}, {"q": "Is the falling-measure technique a test to run on any program?", "a": "no: it is a tool to use; for some functions no measure is known", "w": ["yes, it always finds one", "yes", "no: it never works"], "why": "Falling-measure technique."}, {"q": "To prove a function that calls itself right, what is assumed?", "a": "that it is right on smaller inputs", "w": ["that it stops", "that it is right on every input", "nothing"], "why": "Recursion is induction."}, {"q": "Must the input itself fall at every call?", "a": "no: any whole-number measure will do, as b does for gcd", "w": ["yes, the first input", "yes", "no: nothing must fall"], "why": "Falling-measure technique."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
