(function(C){C["40g"]=(C["40g"]||[]).concat([{"q": "What makes a loop stop?", "a": "a whole number that falls each turn", "w": ["a test at the top", "an invariant", "a jump back"], "why": "A falling measure."}, {"q": "What three duties does an invariant have?", "a": "it holds at the start, survives every turn, and with the failed test gives the goal", "w": ["it falls each turn", "it holds at the end only", "it is true before the program"], "why": "Loop invariants."}, {"q": "From {I ∧ B} c {I}, what is written?", "a": "{I} while B do c {I ∧ ¬B}", "w": ["{I} while B do c {I ∧ B}", "{B} while B do c {I}", "{I} c {¬B}"], "why": "While technique."}, {"q": "Does an invariant prove the loop stops?", "a": "no: stopping needs a falling whole number", "w": ["no: nothing proves it", "yes, with ¬B", "yes"], "why": "Invariants promise, measures stop."}, {"q": "Is x = x a fine invariant?", "a": "no: it is kept, but with ¬B it gives nothing; the invariant must give the goal at the end", "w": ["yes", "no: it is not kept", "yes, it always holds"], "why": "While technique."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
